import * as Ariakit from "@ariakit/react";
import { click, press, q } from "@ariakit/test";
import { render } from "@ariakit/test/react";
import { useState } from "react";

function A() {
  const [show, setShow] = useState(true);
  return (
    <>
      <button>Before</button>
      <Ariakit.Toolbar>
        <Ariakit.ToolbarItem>Bold</Ariakit.ToolbarItem>
        {show && <Ariakit.ToolbarItem>Italic</Ariakit.ToolbarItem>}
        <Ariakit.ToolbarItem>Underline</Ariakit.ToolbarItem>
      </Ariakit.Toolbar>
      <button onClick={() => setShow(!show)}>Toggle Italic</button>
    </>
  );
}

function B({ defaultActive }: { defaultActive?: boolean }) {
  return (
    <>
      <button>Before</button>
      <Ariakit.Toolbar defaultActiveId={defaultActive ? "bold" : undefined}>
        <Ariakit.ToolbarItem id="bold" disabled>Bold</Ariakit.ToolbarItem>
        <Ariakit.ToolbarItem>Italic</Ariakit.ToolbarItem>
        <Ariakit.ToolbarItem>Underline</Ariakit.ToolbarItem>
      </Ariakit.Toolbar>
      <button>After</button>
    </>
  );
}

test("A", async () => {
  await render(<A />);
  await press.Tab();
  await press.Tab();
  expect(q.button("Bold")).toHaveFocus();
  await press.ArrowRight();
  expect(q.button("Italic")).toHaveFocus();
  await click(q.button("Toggle Italic"));
  await press.ShiftTab();
  expect(q.button("Bold")).toHaveFocus();
  await press.ShiftTab();
  expect(q.button("Before")).toHaveFocus();
  await press.Tab();
  expect(q.button("Bold")).toHaveFocus();
  await press.Tab();
  expect(q.button("Toggle Italic")).toHaveFocus();
});

test.each([false, true])("B %s", async (defaultActive) => {
  await render(<B defaultActive={defaultActive} />);
  await press.Tab();
  expect(q.button("Before")).toHaveFocus();
  await press.Tab();
  expect(q.button("Italic")).toHaveFocus();
  await press.Tab();
  expect(q.button("After")).toHaveFocus();
  await press.ShiftTab();
  expect(q.button("Italic")).toHaveFocus();
});
EOF
